#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────



# Verifies the deployed backend against #34 and docs/infra/runbook.md, and
# writes a report to paste on #34.
#
#   verify-deploy.sh
#
# Runs on the admin workstation, on the tailnet, after the runbook's first
# setup or a deploy. It changes nothing: the only write is certbot's
# --dry-run, which issues a staging certificate and throws it away.

REPO="$(cd "$(dirname "$0")/../.." && pwd)"
TF_DIR="$REPO/infra/terraform"
APP_ENV="$REPO/deploy/app/.env"
HOST="cinema-api.strycks.dpdns.org"
REPORT="${REPORT:-deploy-verify-$(date +%F).md}"
RAW=$(mktemp)
SSH_CONFIG=$(mktemp)
trap 'rm -f "$RAW" "$SSH_CONFIG"' EXIT
RESULTS=()
FAILED=0

tf() { terraform -chdir="$TF_DIR" "$@"; }

# record PASS|FAIL "check" ["note"] adds one line to the result checklist.
record() {
  local mark="x"; [[ "$1" == PASS ]] || { mark=" "; FAILED=$((FAILED + 1)); }
  RESULTS+=("- [$mark] $2${3:+ — $3}")
  if [[ "$1" == PASS ]]; then printf '  %s✓ %s%s\n' "$GREEN" "$2" "$RESET"
  else printf '  %s✗ %s%s\n' "$RED" "$2${3:+ ($3)}" "$RESET"; fi
}

# check "name" CMD... records PASS when CMD succeeds.
check() {
  local name="$1"; shift
  if "$@"; then record PASS "$name"; else record FAIL "$name"; fi
}

# on VM 'COMMANDS' runs COMMANDS on cinema-<VM> through the ssh_config output.
on() { ssh -F "$SSH_CONFIG" "cinema-$1" "$2"; }

# raw "title" TEXT appends TEXT to the report's output section.
raw() { printf '== %s\n%s\n\n' "$1" "$2" >> "$RAW"; }

# times_out FROM HOST PORT records PASS when FROM can't reach HOST:PORT and the
# attempt takes the full 3 s: a security group drops, it doesn't refuse.
times_out() {
  local name="$1 → $2:$3 times out" start secs
  start=$(date +%s)
  if on "$1" "nc -zw3 $2 $3" 2>/dev/null; then
    record FAIL "$name" "it connected"
  else
    secs=$(( $(date +%s) - start ))
    if (( secs >= 3 )); then record PASS "$name" "${secs}s"
    else record FAIL "$name" "failed after ${secs}s, refused instead of dropped?"; fi
  fi
}

# write_report "title" writes the checklist and the raw output to $REPORT.
write_report() {
  {
    printf '## %s — %s\n\n' "$1" "$(date '+%F %H:%M')"
    printf 'Against #34 and `docs/infra/runbook.md`.\n\n'
    printf '%s\n' "${RESULTS[@]}"
    printf '\n<details><summary>Output</summary>\n\n```\n'
    cat "$RAW"
    printf '```\n\n</details>\n'
  } > "$REPORT"
}

TOTAL_STAGES=6
banner "Backend deploy: verify (#34)"

stage "Before you start"
say "This checks proxy, app and db against #34. It changes nothing."
for cmd in terraform curl openssl; do
  command -v "$cmd" >/dev/null || { warn "$cmd isn't installed."; exit 1; }
done
tf output -raw ssh_config > "$SSH_CONFIG" || { warn "No ssh_config output in $TF_DIR: run terraform apply first."; exit 1; }
# The VMs get rebuilt, so their host keys aren't pinned here.
cat >> "$SSH_CONFIG" <<'CFG'

Host cinema-*
  BatchMode yes
  ConnectTimeout 5
  StrictHostKeyChecking no
  UserKnownHostsFile /dev/null
  LogLevel ERROR
CFG
FIP=$(tf output -raw proxy_floating_ip)
[[ -f "$APP_ENV" ]] || { warn "No $APP_ENV: see runbook.md → First setup."; exit 1; }
TAG=$(grep -E '^IMAGE_TAG=' "$APP_ENV" | tail -n1 | cut -d= -f2)
check "IMAGE_TAG in deploy/app/.env is a full sha" bash -c '[[ "$0" =~ ^[0-9a-f]{40}$ ]]' "$TAG"
note "Expecting ghcr.io/14m6d4/se-phase-01:$TAG on app."
pause

stage "HTTPS from this workstation"
got=$(curl -fsS --max-time 10 "https://$HOST/actuator/health" 2>&1) || true
raw "curl https://$HOST/actuator/health" "$got"
check "https://$HOST/actuator/health is UP, certificate trusted" bash -c '[[ "$0" == *\"UP\"* ]]' "$got"
pem=$(openssl s_client -connect "$FIP:443" -servername "$HOST" </dev/null 2>/dev/null | openssl x509 2>/dev/null) || true
got=$(openssl x509 -noout -issuer -enddate -ext subjectAltName <<< "$pem" 2>&1) || true
raw "certificate for $HOST" "$got"
check "Certificate from Let's Encrypt, for *.strycks.dpdns.org" \
  bash -c '[[ "$0" == *"Let'"'"'s Encrypt"* && "$0" == *"DNS:*.strycks.dpdns.org"* ]]' "$got"
check "Certificate valid for more than 14 days" bash -c 'openssl x509 -noout -checkend 1209600 <<< "$0" >/dev/null' "$pem"
got=$(openssl s_client -connect "$FIP:443" -servername "unknown.strycks.dpdns.org" </dev/null 2>&1) || true
raw "TLS handshake for unknown.strycks.dpdns.org" "$(tail -n 5 <<< "$got")"
check "Unknown name gets no certificate (handshake rejected)" bash -c '[[ "$0" != *"BEGIN CERTIFICATE"* && "$0" != *"subject="* ]]' "$got"
pause

stage "proxy: nginx and certbot"
say "certbot renew --dry-run asks Let's Encrypt's staging server for a"
say "certificate through Cloudflare: it takes about a minute."
got=$(on proxy 'systemctl is-active nginx; systemctl is-enabled certbot.timer; systemctl is-active certbot.timer; ls /etc/nginx/sites-enabled | paste -sd, -; sudo nginx -t 2>&1 | tail -n1; sudo ss -Hltn "sport = :80" | wc -l' 2>/dev/null) || true
raw "proxy services" "$got"
check "nginx active, config valid" bash -c '[[ "$(head -n1 <<< "$0")" == active && "$0" == *"test is successful"* ]]' "$got"
check "certbot.timer enabled and active" bash -c '[[ "$(sed -n 2,3p <<< "$0")" == $'"'"'enabled\nactive'"'"' ]]' "$got"
check "Only the cinema-api site, nothing on port 80" \
  bash -c '[[ "$(sed -n 4p <<< "$0")" == cinema-api && "$(tail -n1 <<< "$0")" == 0 ]]' "$got"
got=$(on proxy 'sudo certbot renew --dry-run --no-random-sleep-on-renew 2>&1' 2>&1) || true
raw "certbot renew --dry-run" "$(tail -n 8 <<< "$got")"
check "certbot renew --dry-run succeeds" bash -c '[[ "$0" == *"all simulated renewals succeeded"* || "$0" == *"all renewals succeeded"* ]]' "$got"
got=$(on proxy 'sudo grep -E "^(renew_hook|authenticator) " /etc/letsencrypt/renewal/strycks.dpdns.org.conf' 2>/dev/null) || true
raw "renewal config" "$got"
check "Renewal uses dns-cloudflare and reloads nginx" \
  bash -c '[[ "$0" == *dns-cloudflare* && "$0" == *"systemctl reload nginx"* ]]' "$got"
pause

stage "app and db containers"
for vm in app db; do
  got=$(on "$vm" 'cd cinema && docker compose ps -a --format "{{.Service}} {{.State}} {{.Health}} {{.Image}}"; docker compose ps -a --format "{{.Publishers}}"' 2>/dev/null) || true
  raw "$vm docker compose ps" "$got"
  check "$vm: container running and healthy" bash -c '[[ "$(head -n1 <<< "$0")" == "$1 running healthy "* ]]' "$got" "$vm"
done
got=$(on app 'cd cinema && grep -E "^IMAGE_TAG=" .env; docker inspect --format "{{.Config.Image}}" "$(docker compose ps -q app)"' 2>/dev/null) || true
raw "app image" "$got"
check "app runs the IMAGE_TAG from deploy/app/.env" \
  bash -c '[[ "$0" == "IMAGE_TAG=$1"$'"'"'\n'"'"'"ghcr.io/14m6d4/se-phase-01:$1" ]]' "$got" "$TAG"
got=$(on app 'sudo ss -Hltn "sport = :8080" | awk "{print \$4}"' 2>/dev/null) || true
raw "app listeners on 8080" "$got"
check "app: 8080 bound to its tenant IP only" bash -c '[[ "$0" == 192.168.100.20:8080 ]]' "$got"
got=$(on db 'sudo ss -Hltn "sport = :5432" | awk "{print \$4}"' 2>/dev/null) || true
raw "db listeners on 5432" "$got"
check "db: 5432 bound to its tenant IP only" bash -c '[[ "$0" == 192.168.100.30:5432 ]]' "$got"
pause

stage "db: data on the pgdata volume"
got=$(on db 'findmnt -rno TARGET,LABEL -T /srv/pgdata/data; cd cinema && docker inspect --format "{{range .Mounts}}{{.Source}} {{.Destination}}{{end}}" "$(docker compose ps -q db)"; ls -1t /srv/pgdata/dumps/*.dump 2>/dev/null | head -n 5' 2>/dev/null) || true
raw "db data and dumps" "$got"
check "/srv/pgdata/data is on the pgdata volume" bash -c '[[ "$(head -n1 <<< "$0")" == "/srv/pgdata pgdata" ]]' "$got"
check "PostgreSQL's data directory is /srv/pgdata/data" bash -c '[[ "$(sed -n 2p <<< "$0")" == "/srv/pgdata/data /var/lib/postgresql/data" ]]' "$got"
if on db 'test -d /srv/pgdata/dumps' 2>/dev/null; then
  n=$(on db 'ls /srv/pgdata/dumps/*.dump 2>/dev/null | wc -l' 2>/dev/null || echo 0)
  record PASS "/srv/pgdata/dumps exists" "$n dump(s), keep at most 5"
else
  record FAIL "/srv/pgdata/dumps exists"
fi
pause

stage "Network: each tier only from the one in front"
say "Allowed connections must connect. The rest must time out: the security"
say "groups drop the packets."
check "proxy → app:8080 connects" on proxy 'nc -zw3 app 8080'
times_out db app 8080
check "app → db:5432 connects" on app 'nc -zw3 db 5432'
times_out proxy db 5432
pause

write_report "Backend deploy verification"
finish
if (( FAILED )); then warn "$FAILED check(s) failed; see $REPORT"
else note "All checks passed."; fi
note "Paste $REPORT as a comment on issue #34."
printf '\n'
